package local.skyfamily;
import android.graphics.*;import android.view.*;import android.widget.*;import android.text.TextUtils;import org.json.*;import java.util.*;import java.net.URLEncoder;
final class PlanetaryPanel {
 final RefreshActivity host;PlanetaryPanel(RefreshActivity h){host=h;}
 JSONObject saved(String key){try{return new JSONObject(host.get(key));}catch(Exception e){return null;}}
 void open(boolean force){JSONObject location=saved("planetary.location");if(location==null){search();return;}host.page("Planetary data");host.text(label(location));host.button("Change location / town, state",()->search());host.button("Refresh forecast",()->open(true));host.text("Loading weather in Fahrenheit, mph and inches...");String tag=location.optString("latitude")+","+location.optString("longitude");JSONObject cached=saved("planetary.cache");long age=cached==null?Long.MAX_VALUE:System.currentTimeMillis()-cached.optLong("fetched");if(!force&&cached!=null&&tag.equals(cached.optString("place"))&&age>=0&&age<900000L){show(location,cached.optJSONObject("data"),cached.optLong("fetched"),false);return;}int stamp=host.revision;host.work(()->{try{double lat=location.getDouble("latitude"),lon=location.getDouble("longitude");if(Double.isNaN(lat)||Double.isNaN(lon)||Math.abs(lat)>90||Math.abs(lon)>180)throw new Exception("Invalid location coordinates");String url="https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lon+"&current=temperature_2m,relative_humidity_2m,apparent_temperature,is_day,precipitation,weather_code,cloud_cover,pressure_msl,wind_speed_10m,wind_direction_10m,wind_gusts_10m&hourly=temperature_2m,precipitation_probability,wind_speed_10m&daily=weather_code,temperature_2m_max,temperature_2m_min,sunrise,sunset,precipitation_sum,precipitation_probability_max,wind_speed_10m_max,uv_index_max&temperature_unit=fahrenheit&wind_speed_unit=mph&precipitation_unit=inch&timezone=auto&forecast_days=7";JSONObject data=new JSONObject(new String(host.request(url,"GET",null,"",2000000),"UTF-8"));data.getJSONObject("current");long fetched=System.currentTimeMillis();JSONObject record=new JSONObject().put("place",tag).put("fetched",fetched).put("data",data);host.ui.post(()->{if(stamp!=host.revision)return;host.save("planetary.cache",record.toString());show(location,data,fetched,false);});}catch(Exception e){host.ui.post(()->{if(stamp!=host.revision)return;if(cached!=null&&tag.equals(cached.optString("place"))&&cached.optJSONObject("data")!=null)show(location,cached.optJSONObject("data"),cached.optLong("fetched"),true);else host.text("Weather unavailable: "+e.getMessage()+". Check connectivity and try Refresh.");});}});}
 void search(){host.page("Planetary data / choose location");host.text("Type a town and state/region, for example Portland, Oregon. Choose the matching result below. No GPS or API key needed.");EditText query=host.input("Town, state or region",host.get("planetary.query"));LinearLayout results=new LinearLayout(host);results.setOrientation(1);host.button("Search locations",()->{String name=query.getText().toString().trim();if(name.length()<2){host.toast("Enter at least two characters");return;}host.save("planetary.query",name);results.removeAllViews();TextView loading=line("Searching places...",17,host.muted);results.addView(loading);int stamp=host.revision;host.work(()->{JSONObject response=new JSONObject(new String(host.request("https://geocoding-api.open-meteo.com/v1/search?name="+URLEncoder.encode(name,"UTF-8")+"&count=10&language=en&format=json","GET",null,"",1000000),"UTF-8"));JSONArray places=response.optJSONArray("results");host.ui.post(()->{if(stamp!=host.revision||!query.getText().toString().trim().equals(name))return;results.removeAllViews();if(places==null||places.length()==0){results.addView(line("No matches. Try the full town and state name, or town and country.",17,host.muted));return;}for(int i=0;i<places.length();i++){JSONObject place=places.optJSONObject(i);if(place==null)continue;TextView option=line(label(place),18,host.fg);option.setPadding(host.dp(16),host.dp(16),host.dp(16),host.dp(16));option.setBackground(host.press(host.surface));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=host.dp(10);results.addView(option,cp);option.setOnClickListener(v->{host.save("planetary.location",place.toString());host.save("planetary.cache","");open(true);});}});});});host.body.addView(results);if(saved("planetary.location")!=null)host.button("Back to saved location",()->open(false));host.text("Search terms and selected coordinates are sent to Open-Meteo's public services. The chosen location is saved on the frame. Free keyless access is for personal/non-commercial use; provider terms and limits apply.");}
 String label(JSONObject place){ArrayList<String> parts=new ArrayList<>();for(String k:new String[]{"name","admin1","country"}){String v=place.optString(k,"");if(!v.isEmpty()&&!parts.contains(v))parts.add(v);}return TextUtils.join(", ",parts);}
 TextView line(String text,int size,int color){TextView v=new TextView(host);v.setText(text);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,host.dp(4),0,host.dp(6));return v;}
 String number(JSONObject object,String field,int digits,String unit){if(object==null||object.isNull(field))return "Unavailable";double value=object.optDouble(field,Double.NaN);return Double.isNaN(value)||Double.isInfinite(value)?"Unavailable":String.format(Locale.US,"%."+digits+"f",value)+unit;}
 double at(JSONArray a,int i){return a==null||i<0||i>=a.length()||a.isNull(i)?Double.NaN:a.optDouble(i,Double.NaN);}
 String val(double value,int decimals,String unit){return Double.isNaN(value)||Double.isInfinite(value)?"--":String.format(Locale.US,"%."+decimals+"f",value)+unit;}
 String time(String value){int split=value.indexOf('T');return split>=0?value.substring(split+1):value;}
 String direction(double degrees){if(Double.isNaN(degrees))return "";String[] compass={"N","NNE","NE","ENE","E","ESE","SE","SSE","S","SSW","SW","WSW","W","WNW","NW","NNW"};return compass[((int)Math.round(degrees/22.5)%16+16)%16];}
 String condition(int code){if(code==0)return "Clear sky";if(code==1)return "Mainly clear";if(code==2)return "Partly cloudy";if(code==3)return "Overcast";if(code==45||code==48)return "Fog";if(code==51||code==53||code==55)return "Drizzle";if(code==56||code==57)return "Freezing drizzle";if(code==61||code==63||code==65)return "Rain";if(code==66||code==67)return "Freezing rain";if(code==71||code==73||code==75||code==77)return "Snow";if(code>=80&&code<=82)return "Rain showers";if(code==85||code==86)return "Snow showers";if(code==95||code==96||code==99)return "Thunderstorm";return "Condition unavailable";}
 LinearLayout metricRow(){LinearLayout row=new LinearLayout(host);host.body.addView(row);return row;}
 void metric(LinearLayout row,String label,String value){LinearLayout box=new LinearLayout(host);box.setOrientation(1);box.setPadding(host.dp(16),host.dp(14),host.dp(16),host.dp(14));box.setBackground(host.shape(host.surface,host.edge,16));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.setMargins(host.dp(4),host.dp(4),host.dp(4),host.dp(4));row.addView(box,cp);box.addView(line(label,13,host.muted));box.addView(line(value,21,host.fg));}
 void show(JSONObject location,JSONObject data,long fetched,boolean stale){if(data==null){host.text("No weather data available");return;}host.page("Planetary data");host.text(label(location));host.button("Change location",()->search());host.button("Refresh forecast",()->open(true));if(stale)host.text("OFFLINE / STALE CACHED FORECAST. Live refresh failed; check the timestamp before relying on this data.");JSONObject current=data.optJSONObject("current");if(current==null){host.text("Provider returned no current conditions");return;}int code=current.optInt("weather_code",-1);LinearLayout hero=new LinearLayout(host);hero.setGravity(Gravity.CENTER_VERTICAL);hero.setPadding(host.dp(22),host.dp(18),host.dp(22),host.dp(18));hero.setBackground(host.shape(0xff243759,0,22));hero.addView(new WeatherIcon(code,current.optInt("is_day",1)==1),new LinearLayout.LayoutParams(host.dp(88),host.dp(88)));LinearLayout readings=new LinearLayout(host);readings.setOrientation(1);readings.setPadding(host.dp(22),0,0,0);hero.addView(readings,new LinearLayout.LayoutParams(0,-2,1));readings.addView(line(number(current,"temperature_2m",0," °F"),46,host.fg));readings.addView(line(condition(code),20,host.fg));readings.addView(line("Feels like "+number(current,"apparent_temperature",0," °F"),15,host.muted));host.body.addView(hero);host.text("Model current time: "+current.optString("time")+" / "+data.optString("timezone")+". Forecast/model data, not a local station observation.");LinearLayout first=metricRow();metric(first,"Wind",number(current,"wind_speed_10m",0," mph")+" "+direction(current.optDouble("wind_direction_10m",Double.NaN)));metric(first,"Gusts",number(current,"wind_gusts_10m",0," mph"));LinearLayout second=metricRow();metric(second,"Humidity",number(current,"relative_humidity_2m",0,"%"));metric(second,"Sea-level pressure",val(current.optDouble("pressure_msl",Double.NaN)*0.029529983,2," inHg"));LinearLayout third=metricRow();metric(third,"Precipitation (current interval)",number(current,"precipitation",2," in"));metric(third,"Cloud cover",number(current,"cloud_cover",0,"%"));JSONObject hourly=data.optJSONObject("hourly");if(hourly!=null){host.section("Next hours / local forecast time");HorizontalScrollView scroll=new HorizontalScrollView(host);LinearLayout hours=new LinearLayout(host);scroll.addView(hours);host.body.addView(scroll);JSONArray times=hourly.optJSONArray("time");String now=current.optString("time");int added=0;if(times!=null)for(int i=0;i<times.length()&&added<12;i++){String t=times.optString(i);if(t.compareTo(now)<0)continue;LinearLayout card=new LinearLayout(host);card.setOrientation(1);card.setPadding(host.dp(12),host.dp(12),host.dp(12),host.dp(12));card.setBackground(host.shape(host.surface,host.edge,14));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(host.dp(112),-2);cp.setMargins(host.dp(3),host.dp(3),host.dp(3),host.dp(3));hours.addView(card,cp);card.addView(line(time(t),14,host.muted));card.addView(line(val(at(hourly.optJSONArray("temperature_2m"),i),0," °F"),23,host.fg));card.addView(line(val(at(hourly.optJSONArray("precipitation_probability"),i),0,"% rain chance"),11,host.accent));card.addView(line(val(at(hourly.optJSONArray("wind_speed_10m"),i),0," mph"),13,host.muted));added++;}}JSONObject daily=data.optJSONObject("daily");if(daily!=null){host.section("Seven-day outlook");JSONArray dates=daily.optJSONArray("time");if(dates!=null)for(int i=0;i<dates.length();i++){LinearLayout card=new LinearLayout(host);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(host.dp(12),host.dp(12),host.dp(12),host.dp(12));card.setBackground(host.shape(host.surface,host.edge,16));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=host.dp(10);host.body.addView(card,cp);int dailyCode=(int)at(daily.optJSONArray("weather_code"),i);card.addView(new WeatherIcon(dailyCode,true),new LinearLayout.LayoutParams(host.dp(42),host.dp(42)));LinearLayout description=new LinearLayout(host);description.setOrientation(1);description.setPadding(host.dp(14),0,0,0);card.addView(description,new LinearLayout.LayoutParams(0,-2,1));description.addView(line(dates.optString(i)+" / "+condition(dailyCode),16,host.fg));description.addView(line("High "+val(at(daily.optJSONArray("temperature_2m_max"),i),0," °F")+" / Low "+val(at(daily.optJSONArray("temperature_2m_min"),i),0," °F"),18,host.fg));description.addView(line("Precip "+val(at(daily.optJSONArray("precipitation_sum"),i),2," in")+" / Chance "+val(at(daily.optJSONArray("precipitation_probability_max"),i),0,"%")+" / Wind "+val(at(daily.optJSONArray("wind_speed_10m_max"),i),0," mph"),12,host.muted));if(i==0){JSONArray rise=daily.optJSONArray("sunrise"),set=daily.optJSONArray("sunset");description.addView(line("Sunrise "+(rise==null?"--":time(rise.optString(i)))+" / Sunset "+(set==null?"--":time(set.optString(i)))+" / UV max "+val(at(daily.optJSONArray("uv_index_max"),i),1,""),12,host.accent));}}}host.text("Weather: Open-Meteo / location search: GeoNames via Open-Meteo. Retrieved on this device: "+new Date(fetched)+". Cached for 15 minutes; stale fallback is labelled. Not an emergency-alert service. No API key for personal/non-commercial access.");}
 class WeatherIcon extends View {int code;boolean day;Paint p=new Paint(3);WeatherIcon(int c,boolean d){super(host);code=c;day=d;setContentDescription(condition(c));}protected void onDraw(Canvas c){c.save();c.scale(getWidth()/100f,getHeight()/100f);p.setStrokeWidth(4);p.setStrokeCap(Paint.Cap.ROUND);p.setStyle(Paint.Style.STROKE);if(code<=2&&code>=0){p.setColor(0xffffcf92);c.drawCircle(40,36,16,p);if(day)for(int i=0;i<8;i++){c.save();c.rotate(i*45,40,36);c.drawLine(40,9,40,14,p);c.restore();}}if(code>=2||code<0){p.setColor(0xffd5e3ff);c.drawRoundRect(new RectF(17,43,85,68),12,12,p);c.drawArc(new RectF(33,25,67,59),180,180,false,p);}if(code>=51&&code<=67||code>=80&&code<=82){p.setColor(0xff8dbbff);for(int x=30;x<=74;x+=20)c.drawLine(x,77,x-4,87,p);}if(code>=71&&code<=77||code==85||code==86){p.setColor(0xffd5e3ff);for(int x=30;x<=74;x+=20){c.drawLine(x,77,x,89,p);c.drawLine(x-5,83,x+5,83,p);}}if(code>=95){p.setColor(0xffffcf92);Path bolt=new Path();bolt.moveTo(53,69);bolt.lineTo(43,83);bolt.lineTo(56,83);bolt.lineTo(48,96);c.drawPath(bolt,p);}if(code==45||code==48){p.setColor(0xffa4b8d4);c.drawLine(20,78,78,78,p);c.drawLine(30,87,87,87,p);}c.restore();}}
}
